import re, pathlib
root = pathlib.Path(__file__).parent
def lib(p):
    t = (root/p).read_text()
    t = re.sub(r'//# sourceMappingURL=.*', '', t)
    return t.replace('</script', '<\\/script')
shell = (root/'src/shell.html').read_text()
app = '\n'.join((root/'src'/f).read_text() for f in ['core.js','ui.js','props.js','help.js','comp.js','compui.js','clip.js','linkui.js','checkui.js','maker.js','gamedata.js','io.js'])
assert '</script' not in app
out = shell.replace('/*VENDOR_JSPDF*/', lib('node_modules/jspdf/dist/jspdf.umd.min.js')) \
           .replace('/*VENDOR_SVG2PDF*/', lib('node_modules/svg2pdf.js/dist/svg2pdf.umd.min.js')) \
           .replace('/*ICONS*/', (root/'src/icons.js').read_text()) \
           .replace('/*APP*/', app)
(root.parent/'index.html').write_text(out)
print('built', len(out)//1024, 'KB')

# ---- Node renderer: the same drawing code, no browser needed ----
node_src = '\n'.join((root/'src'/f).read_text() for f in ['icons.js','core.js','comp.js','gamedata.js'])
node_out = '''#!/usr/bin/env node
// Hexcraft renderer for Node.js — draws a Hexcraft project (.hexmap.json) exactly as the editor
// exports it, without a browser. Generated by source/build.py from icons.js, core.js, comp.js and
// gamedata.js; do not edit by hand. Needs Node 16+ and nothing else.
//
//   const hc = require('./hexcraft-render.cjs');
//   hc.render(project, { art: true })   -> SVG string ("art only": no grid, cities, text…)
//   hc.render(project)                  -> SVG string of the full map, as File › Export › SVG
//   hc.gameData(project)                -> the .game.json object, as File › Export game data
//   hc.pageBounds(project)              -> { x, y, w, h } page area (the SVG viewBox)
//
//   node hexcraft-render.cjs map.hexmap.json [--art] [--track] [--links] [--no-sides]
//        [--transparent] [--scale 2] [--game-data] [-o out.svg]
//
// project: a parsed object or the JSON text. Text widths are estimated (no font metrics), so
// tables and long labels can differ slightly from the editor; art-only output has no text.
(function () {
''' + node_src + r'''

function load(project) {
  const obj = typeof project === 'string' ? JSON.parse(project) : JSON.parse(JSON.stringify(project));
  P = migrate(obj); applyShapeVoids(); return P;
}
function render(project, o = {}) {
  load(project);
  const art = o.art ? { sides: o.sides !== false, track: !!o.track, links: !!o.links } : null;
  const b = o.bounds || pageBounds(), k = o.scale || 1;
  return mapSVG({ art, bg: o.background !== false, bounds: b, pxW: b.w * k, pxH: b.h * k });
}
const api = { render, gameData: (project) => { load(project); return gameData(); }, pageBounds: (project) => { load(project); return pageBounds(); }, version: 1 };
if (typeof module !== 'undefined') module.exports = api;

if (typeof require !== 'undefined' && typeof module !== 'undefined' && require.main === module) {
  const fs = require('fs'), args = process.argv.slice(2);
  const file = args.find((a, i) => !a.startsWith('-') && args[i - 1] !== '-o' && args[i - 1] !== '--scale');
  if (!file) { console.error('usage: node hexcraft-render.cjs map.hexmap.json [--art] [--track] [--links] [--no-sides] [--transparent] [--scale N] [--game-data] [-o out]'); process.exit(1); }
  const has = (f) => args.includes(f), val = (f) => { const i = args.indexOf(f); return i >= 0 ? args[i + 1] : undefined; };
  const text = fs.readFileSync(file, 'utf8');
  const out = has('--game-data') ? JSON.stringify(api.gameData(text), null, 1)
    : render(text, { art: has('--art'), track: has('--track'), links: has('--links'), sides: !has('--no-sides'), background: !has('--transparent'), scale: +val('--scale') || 1 });
  if (val('-o')) fs.writeFileSync(val('-o'), out); else process.stdout.write(out);
}
})();
'''
(root.parent/'hexcraft-render.cjs').write_text(node_out)
print('built node renderer', len(node_out)//1024, 'KB')

# ---- help / hover-tip coverage check ----
import re as _re
src = {f: (root/'src'/f).read_text() for f in ['core.js','ui.js','props.js','help.js','comp.js','compui.js','clip.js','linkui.js','checkui.js','maker.js','gamedata.js','io.js']}
shell_t = (root/'src/shell.html').read_text(); help_t = src['help.js']; allsrc = ''.join(src.values())
acts = set(_re.findall(r'data-act="([a-zA-Z0-9-]+)"', allsrc + shell_t))
missing_acts = sorted(a for a in acts if not a.startswith('help-') and not _re.search(r"(['\"]?)%s\1\s*:" % _re.escape(a), help_t))
labels = set(_re.findall(r"F\('([^']+)'", src['props.js'] + src['compui.js'] + src['linkui.js']))
missing_fields = sorted(l for l in labels if ("'%s':" % l) not in help_t and ("'%s':" % l) not in src['compui.js'])
tools = [t for t in _re.findall(r"\['([a-z]+)', '[A-Z]', '", src['ui.js'] + src['linkui.js'])]
missing_tools_help = [t for t in tools if t not in ('types',) and not _re.search(r"\b%s:\s*'|TOOL_HINTS\.%s\s*=" % (t, t), src['ui.js'] + src['linkui.js'])]
help_secs = set(_re.findall(r"^  \['([a-z]+)', '", help_t, _re.M))
menu_secs = set(_re.findall(r'data-act="help-([a-z]+)"', shell_t))
if missing_acts or missing_fields or missing_tools_help or (help_secs - menu_secs) or (menu_secs - help_secs):
    print('HELP COVERAGE GAPS:')
    if missing_acts: print('  buttons without hover tips:', missing_acts)
    if missing_fields: print('  fields without hover tips:', missing_fields)
    if missing_tools_help: print('  tools without hints:', missing_tools_help)
    if help_secs - menu_secs: print('  help sections missing from Help menu:', sorted(help_secs - menu_secs))
    if menu_secs - help_secs: print('  Help menu items without a section:', sorted(menu_secs - help_secs))
else:
    print('help coverage OK:', len(acts), 'buttons,', len(labels), 'fields,', len(help_secs), 'help sections')
